 static bool LoadSession(){try{byte[] bytes=ProtectedData.Unprotect(File.ReadAllBytes(Path.Combine(Profile,"native-session.protected")),null,DataProtectionScope.CurrentUser);var s=Parse(Encoding.UTF8.GetString(bytes));var u=new Uri(Text(s,"origin"));if(u.Scheme!="http"||u.Host!="127.0.0.1"||u.Port<1024)return false;var p=Process.GetProcessById(Convert.ToInt32(s["pid"]));if(p.HasExited)return false;Origin=u.GetLeftPart(UriPartial.Authority);Token=Text(s,"token");return Token.Length==64;}catch{return false;}}
