   string node=Arguments.ContainsKey("node")?Arguments["node"]:Path.Combine(Home,"runtime","node.exe"),entry=Arguments.ContainsKey("backend")?Arguments["backend"]:Path.Combine(Home,"app","src","native-backend.cjs");
