  var menu=new ContextMenuStrip();menu.Items.Add(Tr("Open Flow","فتح Flow"),null,async delegate{await Open("main",new Dictionary<string,object>());});menu.Items.Add(Tr("Pause all","إيقاف الكل"),null,async delegate{await Action("pauseAll",new{});});menu.Items.Add(new ToolStripSeparator());menu.Items.Add(Tr("Exit Flow","خروج من Flow"),null,async delegate{await Action("quit",new{});Exit();});Tray.ContextMenuStrip=menu;
