 internal static async Task<object> Request(string route,object data=null){
  using(var request=new HttpRequestMessage(data==null?HttpMethod.Get:HttpMethod.Post,Origin+route)){request.Headers.Add("x-flow-token",Token);if(data!=null)request.Content=new StringContent(Json(data),Encoding.UTF8,"application/json");using(var response=await Client.SendAsync(request)){var result=Parse(await response.Content.ReadAsStringAsync());if(!response.IsSuccessStatusCode)throw new Exception(Text(result,"error","Flow could not complete the request."));return result;}}
 }
 static void QueueLaunch(string[] args){if(!args.Any(a=>new[]{"/d","/s"}.Contains(a.ToLowerInvariant())))return;string inbox=Path.Combine(Profile,"LaunchInbox");Directory.CreateDirectory(inbox);if(Directory.GetFiles(inbox,"*.json").Length>=100)throw new IOException("Flow's command queue is busy. Try again after the pending links are added.");string file=Path.Combine(inbox,Guid.NewGuid().ToString("N")+".json");File.WriteAllText(file+".tmp",Json(args),new UTF8Encoding(false));File.Move(file+".tmp",file);}
 static async Task DrainLaunches(){if(Launching)return;Launching=true;try{string inbox=Path.Combine(Profile,"LaunchInbox");if(!Directory.Exists(inbox))return;foreach(string file in Directory.GetFiles(inbox,"*.json").OrderBy(File.GetCreationTimeUtc).Take(4)){if(new FileInfo(file).Length>65536){File.Move(file,file+".rejected");continue;}string[] args=Serializer().Deserialize<string[]>(File.ReadAllText(file));if(args==null||args.Length>256){File.Move(file,file+".rejected");continue;}File.Move(file,file+".processing");try{await Action("nativeCLI",new{args=args});File.Delete(file+".processing");}catch(Exception e){Diagnostic("launch-command-failed "+e.GetType().Name);foreach(var w in Windows.Values.ToArray())w.Event("error",e.Message);File.Move(file+".processing",file+".failed");}}}finally{Launching=false;}}
 internal static async Task<Dictionary<string,object>> State(){var state=(Dictionary<string,object>)await Request("/api/state");if(state.ContainsKey("settings"))Settings=(Dictionary<string,object>)state["settings"];return state;}
