 static bool StartupBlocked(){var approval=Registry.GetValue("HKEY_CURRENT_USER\\Software\\Microsoft\\Windows\\CurrentVersion\\Explorer\\StartupApproved\\Run",StartupName,null)as byte[];return approval!=null&&approval.Length>0&&approval[0]!=0&&approval[0]!=2;}
 static bool StartupEnabled(){return !StartupBlocked()&&!String.IsNullOrEmpty(Convert.ToString(Registry.GetValue("HKEY_CURRENT_USER\\Software\\Microsoft\\Windows\\CurrentVersion\\Run",StartupName,null)));}
 static bool SetStartup(bool enabled,bool explicitChoice){using(var key=Registry.CurrentUser.CreateSubKey("Software\\Microsoft\\Windows\\CurrentVersion\\Run")){if(enabled){string launcher=Environment.GetEnvironmentVariable("PORTABLE_EXECUTABLE_FILE");if(String.IsNullOrEmpty(launcher))launcher=Application.ExecutablePath;if(!File.Exists(launcher))throw new FileNotFoundException("The startup launcher is missing. Open Flow from a permanent location first.");key.SetValue(StartupName,Arg(launcher)+" --background --profile "+Arg(Profile)+" --port "+new Uri(Origin).Port);if(explicitChoice)using(var approved=Registry.CurrentUser.CreateSubKey("Software\\Microsoft\\Windows\\CurrentVersion\\Explorer\\StartupApproved\\Run"))approved.DeleteValue(StartupName,false);}else key.DeleteValue(StartupName,false);}if(enabled&&!StartupEnabled())throw new IOException("Windows did not enable Flow startup. Check Startup apps in Windows Settings.");return StartupEnabled();}
 internal static async Task<FlowForm> Open(string kind,Dictionary<string,object> data,bool hidden=false){
  var allowed=new HashSet<string>(new[]{"main","settings","add","download-info","details","scheduler","batch","grabber","integration","logs","about","complete","smart","power","library","updates","tools","shutdown","drop"});
  if(!allowed.Contains(kind))throw new Exception("Unknown Flow window.");string id=Text(data,"id"),key=kind+(new[]{"details","download-info","complete"}.Contains(kind)?":"+id:"");FlowForm w;
  if(Windows.TryGetValue(key,out w)&&!w.IsDisposed){if(!hidden)await Present(w);if(data.ContainsKey("tab"))w.Event("tool-context",data);return w;}
  w=new FlowForm(kind,key,data);Windows[key]=w;try{await w.Prepare();ApplyFrame(w);if(!hidden)await Present(w);return w;}catch{Windows.Remove(key);w.Dispose();throw;}
 }
 internal static async Task Restore(){FlowForm w;if(Windows.TryGetValue(LastWindow,out w)&&!w.IsDisposed){w.Show();w.WindowState=FormWindowState.Normal;w.Activate();return;}await Open("main",new Dictionary<string,object>());}
 internal static void Remember(FlowForm w){LastWindow=w.Kind=="details"||w.Kind=="complete"?w.Key:"main";}
 internal static void Removed(FlowForm w){Windows.Remove(w.Key);if(!Quitting&&(w.Kind=="download-info"||w.Kind=="shutdown"))Action("nativeWindowClosed",new{id=w.DownloadId,kind=w.Kind}).ContinueWith(t=>{});}
