 static string Human(double n){return n>=1048576?(n/1048576).ToString("0.0")+" MB":(n/1024).ToString("0")+" KB";}
 static void UpdateTray(Dictionary<string,object> state){var raw=state.ContainsKey("downloads")?state["downloads"]as object[]:null;if(raw==null)return;var rows=raw.Cast<Dictionary<string,object>>().ToArray();var active=rows.Where(d=>new[]{"probing","downloading","processing"}.Contains(Text(d,"status"))).ToArray();double bytes=active.Sum(d=>Convert.ToDouble(d["downloaded"])),total=active.Sum(d=>Convert.ToDouble(d["size"])),rate=active.Sum(d=>Convert.ToDouble(d["speed"]));if(Tray!=null){string label="Flow · "+active.Length+Tr(" active · "," نشط · ")+Human(bytes)+" / "+Human(total)+" · "+Human(rate)+"/s";Tray.Text=label.Substring(0,Math.Min(63,label.Length));if(!Tray.ContextMenuStrip.Visible){var menu=new ContextMenuStrip();menu.Items.Add(Tr("Open Flow","فتح Flow"),null,async delegate{await Open("main",new Dictionary<string,object>());});foreach(var row in (active.Length>0?active:rows).Take(5)){string id=Text(row,"id"),name=Text(row,"name");menu.Items.Add(name.Substring(0,Math.Min(38,name.Length))+" · "+Human(Convert.ToDouble(row["downloaded"]))+" / "+Human(Convert.ToDouble(row["size"])),null,async delegate{await Open("details",new Dictionary<string,object>{{"id",id}});});}menu.Items.Add(Tr("Pause all","إيقاف الكل"),null,async delegate{await Action("pauseAll",new{});});menu.Items.Add(Tr("Exit Flow","خروج من Flow"),null,async delegate{await Action("quit",new{});Exit();});var old=Tray.ContextMenuStrip;Tray.ContextMenuStrip=menu;if(old!=null)old.Dispose();}}foreach(var w in Windows.Values.ToArray()){var d=rows.FirstOrDefault(r=>Text(r,"id")==w.DownloadId);double b=w.Kind=="main"?bytes:d!=null?Convert.ToDouble(d["downloaded"]):0,t=w.Kind=="main"?total:d!=null?Convert.ToDouble(d["size"]):0;bool running=w.Kind=="main"?active.Length>0:d!=null&&active.Contains(d);ApplyFrame(w);FlowTaskbar.Progress(w.Handle,running,b,t);}}
 static async Task Handle(string type,object raw){var data=raw as Dictionary<string,object>??new Dictionary<string,object>();object result=true;string error=null;try{
  if(type=="window")await Open(Text(data,"kind"),data);
  else if(type=="external"){var u=new Uri(Text(data,"url"));if(u.Scheme!="http"&&u.Scheme!="https")throw new Exception("Unsupported link.");Process.Start(new ProcessStartInfo(u.AbsoluteUri){UseShellExecute=true});}
  else if(type=="open"){string file=Text(data,"file");if(!File.Exists(file)&&!Directory.Exists(file))throw new FileNotFoundException("This file is no longer available.");Process.Start(new ProcessStartInfo(file){UseShellExecute=true});}
  else if(type=="folder")Process.Start("explorer.exe","/select,"+Arg(Text(data,"file")));
  else if(type=="chooseDirectory"){using(var dlg=new FolderBrowserDialog()){result=dlg.ShowDialog()==DialogResult.OK?dlg.SelectedPath:null;}}
  else if(type=="chooseSound"){using(var dlg=new OpenFileDialog { Filter="WAV audio|*.wav" })result=dlg.ShowDialog()==DialogResult.OK?dlg.FileName:null;}
  else if(type=="scale"){foreach(var w in Windows.Values)w.View.ZoomFactor=Convert.ToDouble(data["value"]);}
  else if(type=="startup")result=SetStartup(Convert.ToBoolean(data["enabled"]),true);
  else if(type=="chromeExtensions"){string chrome=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ProgramFiles),"Google","Chrome","Application","chrome.exe");if(!File.Exists(chrome))chrome=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Google","Chrome","Application","chrome.exe");if(!File.Exists(chrome))throw new Exception("Open chrome://extensions in Chrome.");Process.Start(chrome,"chrome://extensions");}
  else if(type=="complete"){if(Tray!=null){Tray.BalloonTipTitle=Tr("Download complete","اكتمل التحميل");Tray.BalloonTipText=Text(data,"name");Tray.ShowBalloonTip(5000);}foreach(var w in Windows.Values)w.Event("complete",raw);}
  else if(type=="error"){foreach(var w in Windows.Values)w.Event("error",raw);}
  else if(type=="quit"){Exit();return;}
  else if(type=="wake"){}
  else if(type=="vpn"){string name=Text(data,"name");if(String.IsNullOrWhiteSpace(name))throw new Exception("Choose a saved Windows VPN connection first.");Process.Start(new ProcessStartInfo(Path.Combine(Environment.SystemDirectory,"rasdial.exe"),Arg(name)+(Text(data,"command")=="disconnect"?" /disconnect":"")){UseShellExecute=false,CreateNoWindow=true});}
 }catch(Exception e){error=e.Message;}if(data.ContainsKey("requestId"))await Action("nativeReply",new{id=Text(data,"requestId"),value=result,error=error});}
 static void Exit(){if(Quitting)return;Quitting=true;if(PollTimer!=null)PollTimer.Stop();if(Tray!=null){Tray.Visible=false;Tray.Dispose();}foreach(var w in Windows.Values.ToArray())w.Dispose();Context.ExitThread();}
 static async Task RunQA(){var steps=Serializer().Deserialize<object[]>(File.ReadAllText(Arguments["qa"]));var results=new List<object>();try{var main=Windows["main"];for(int i=0;i<200;i++){var r=await main.Evaluate("typeof initialized!=='undefined'&&initialized");if(r is bool&&(bool)r)break;await Task.Delay(50);}foreach(Dictionary<string,object> step in steps){FlowForm w;string key=Text(step,"window","main");if(key=="@download")key="details:"+Convert.ToString(await Windows["main"].Evaluate("window.qaDownloadId"));if(!Windows.TryGetValue(key,out w))throw new Exception("QA window missing: "+key);if(step.ContainsKey("delay"))await Task.Delay(Convert.ToInt32(step["delay"]));object value=null;string operation=Text(step,"operation");if(operation=="minimize")w.WindowState=FormWindowState.Minimized;else if(operation=="restoreTray")await Restore();else if(operation=="inspect")value=new{visible=w.Visible,minimized=w.WindowState==FormWindowState.Minimized,key=w.Key,width=w.Width,height=w.Height,dpi=DpiScale(),recoveries=w.Recoveries};else if(operation=="crashRenderer"){try{await Task.WhenAny(w.View.CoreWebView2.CallDevToolsProtocolMethodAsync("Page.crash","{}"),Task.Delay(2000));}catch{}}else if(operation=="crashBrowser")Process.GetProcessById((int)w.View.CoreWebView2.BrowserProcessId).Kill();if(step.ContainsKey("script")){for(int attempt=0;;attempt++){try{value=await w.Evaluate(Text(step,"script"));break;}catch(Exception qaError){if(operation!="awaitInterface"||attempt>=100)throw;Diagnostic("qa-recovery-wait "+qaError.GetType().Name);}await Task.Delay(100);}}if(step.ContainsKey("capture")){using(var file=File.Create(Text(step,"capture")))await w.View.CoreWebView2.CapturePreviewAsync(CoreWebView2CapturePreviewImageFormat.Png,file);}results.Add(new{step=Text(step,"name"),value=value});File.WriteAllText(Arguments["qa"]+".progress.json",Json(results));}File.WriteAllText(Arguments["qa"]+".result.json",Json(new{passed=results.Count,results=results}));}catch(Exception e){File.WriteAllText(Arguments["qa"]+".result.json",Json(new{error=e.ToString(),results=results}));}await Action("quit",new{});Exit();}
 internal sealed class FlowForm:Form {
  internal WebView2 View=new WebView2();internal string Kind,Key,DownloadId;Dictionary<string,object> Data;internal int Recoveries;bool Recovering;string PageUrl;DateTime RecoveryStart=DateTime.UtcNow;
  internal FlowForm(string kind,string key,Dictionary<string,object> data){Kind=kind;Key=key;Data=data;DownloadId=FlowWebView.Text(data,"id");Text="Flow Download Manager";double dpi=DpiScale();var area=Screen.FromPoint(Cursor.Position).WorkingArea;Width=Math.Min(area.Width,(int)((kind=="main"?1280:kind=="details"?550:kind=="complete"?490:850)*dpi));Height=Math.Min(area.Height,(int)((kind=="main"?800:kind=="details"?460:kind=="complete"?370:740)*dpi));MinimumSize=new Size((int)((kind=="main"?640:360)*dpi),(int)(260*dpi));AutoScaleMode=AutoScaleMode.Dpi;StartPosition=FormStartPosition.CenterScreen;Icon=System.Drawing.Icon.ExtractAssociatedIcon(Application.ExecutablePath);if(kind=="drop"){Width=(int)(210*dpi);Height=(int)(170*dpi);MinimumSize=new Size(160,120);TopMost=true;FormBorderStyle=FormBorderStyle.SizableToolWindow;ShowInTaskbar=false;}View.Dock=DockStyle.Fill;Controls.Add(View);Resize+=delegate {if(WindowState==FormWindowState.Minimized){Remember(this);if(Flag("minimizeToTray",true))Hide();}Event("visibility",new{visible=Visible&&WindowState!=FormWindowState.Minimized});};FormClosing+=(sender,e)=>{if(!Quitting&&Kind=="main"&&Flag("closeToTray",true)){e.Cancel=true;Hide();return;}};FormClosed+=delegate{Removed(this);};Shown+=delegate{Event("visibility",new{visible=true});};}
  internal async Task Prepare(){var env=await CoreWebView2Environment.CreateAsync(null,Path.Combine(Profile,"WebView2"));await View.EnsureCoreWebView2Async(env);var c=View.CoreWebView2;c.Settings.AreDefaultContextMenusEnabled=false;c.Settings.AreDevToolsEnabled=false;c.Settings.IsStatusBarEnabled=false;c.PermissionRequested+=(s,e)=>e.State=CoreWebView2PermissionState.Deny;c.NewWindowRequested+=(s,e)=>e.Handled=true;c.NavigationStarting+=(s,e)=>{Uri u;if(!Uri.TryCreate(e.Uri,UriKind.Absolute,out u)||u.GetLeftPart(UriPartial.Authority)!=Origin)e.Cancel=true;};c.DocumentTitleChanged+=delegate{Text=c.DocumentTitle;};c.ProcessFailed+=async(s,e)=>{Diagnostic("process-failed "+Kind+" "+e.ProcessFailedKind);await Recover(e.ProcessFailedKind==CoreWebView2ProcessFailedKind.BrowserProcessExited);};
   c.WebMessageReceived+=async(s,e)=>{try{var source=new Uri(e.Source);if(source.GetLeftPart(UriPartial.Authority)!=Origin)return;var m=Parse(e.WebMessageAsJson);string id=FlowWebView.Text(m,"id"),kind=FlowWebView.Text(m,"kind");object value=null;string error=null;try{var data=m.ContainsKey("data")?m["data"]as Dictionary<string,object>:null;data=data??new Dictionary<string,object>();if(kind=="state"){var state=await State();state["windowVisible"]=Visible&&WindowState!=FormWindowState.Minimized;value=state;}else{string action=FlowWebView.Text(m,"action");if(kind!="action"||!AllowedActions.Contains(action))throw new Exception("This action is not available.");if(Kind=="drop"&&action!="add"&&action!="dropClose")throw new Exception("This action is not available in the drop basket.");if(action=="window"){await Open(FlowWebView.Text(data,"kind"),data);value=true;}else if(action=="windowHide"){Remember(this);Hide();value=true;}else if(action=="windowMinimize"){WindowState=FormWindowState.Minimized;value=true;}else if(action=="windowClose"){Close();value=true;}else if(action=="windowReload"){Recoveries=0;c.Navigate(PageUrl);value=true;}else if(action=="drop"){await Open("drop",new Dictionary<string,object>());value=true;}else if(action=="dropClose"){FlowForm basket;if(Windows.TryGetValue("drop",out basket))basket.Close();value=true;}else if(Kind=="drop"&&action=="add")value=await Action("nativeDropAdd",data);else value=await Action(action,data);}}catch(Exception problem){error=problem.Message;}if(!IsDisposed)c.PostWebMessageAsJson(Json(new{id=id,value=value,error=error}));}catch{}};
   await c.AddScriptToExecuteOnDocumentCreatedAsync(File.ReadAllText(Path.Combine(Home,"bridge.js")));string url=Origin+"/";if(Kind=="drop")url=Origin+"/drop.html";else if(Kind!="main"){var query=new List<string>{"window="+Uri.EscapeDataString(Kind)};foreach(string k in new[]{"id","tab","url"})if(Data.ContainsKey(k))query.Add(k+"="+Uri.EscapeDataString(Convert.ToString(Data[k])));url+="?"+String.Join("&",query);}PageUrl=url;var loaded=new TaskCompletionSource<bool>();EventHandler<CoreWebView2NavigationCompletedEventArgs> finished=null;finished=(sender,args)=>{if(c.Source==url){c.NavigationCompleted-=finished;if(args.IsSuccess)loaded.TrySetResult(true);else loaded.TrySetException(new Exception("Flow could not load this window. Reopen it to retry."));}};c.NavigationCompleted+=finished;c.Navigate(url);if(await Task.WhenAny(loaded.Task,Task.Delay(20000))!=loaded.Task){c.NavigationCompleted-=finished;throw new Exception("Flow window loading timed out.");}await loaded.Task;View.ZoomFactor=Settings.ContainsKey("textScale")?Convert.ToDouble(Settings["textScale"])/100:1;
  }
  internal async Task Recover(bool recreate){if(Recovering||IsDisposed||Quitting)return;Recovering=true;try{if((DateTime.UtcNow-RecoveryStart).TotalMinutes>5){Recoveries=0;RecoveryStart=DateTime.UtcNow;}bool limited=++Recoveries>3;await Task.Delay(500);if(IsDisposed||Quitting)return;if(recreate){var old=View;Controls.Remove(old);old.Dispose();View=new WebView2 { Dock=DockStyle.Fill };Controls.Add(View);await Prepare();}else View.CoreWebView2.Navigate(PageUrl);if(limited)View.CoreWebView2.Navigate(Origin+"/recovery.html?lang="+Text(Settings,"language","en"));}catch(Exception recoveryError){Diagnostic("recovery-failed "+Kind+" "+recoveryError.GetType().Name);if(!IsDisposed){var retry=new Button {Text="Restart interface",Dock=DockStyle.Fill};retry.Click+=async delegate{Controls.Remove(retry);retry.Dispose();Recoveries=0;await Recover(true);};Controls.Add(retry);retry.BringToFront();}}finally{Recovering=false;}}
  internal void Event(string type,object data){try{if(View.CoreWebView2!=null&&!IsDisposed)View.CoreWebView2.PostWebMessageAsJson(Json(new{eventName=type,value=data}));}catch{}}
  internal async Task<object> Evaluate(string expression){string text=await View.CoreWebView2.CallDevToolsProtocolMethodAsync("Runtime.evaluate",Json(new{expression=expression,awaitPromise=true,returnByValue=true}));var r=Parse(text);if(r.ContainsKey("exceptionDetails"))throw new Exception(Json(r["exceptionDetails"]));var value=(Dictionary<string,object>)r["result"];return value.ContainsKey("value")?value["value"]:null;}
 }
}
